import React, { useState, useEffect } from 'react';
import API from '../api/axios';
import { Phone, MessageSquare, Search, Calendar, Bike, RefreshCw } from 'lucide-react';
import { useSocket } from '../context/SocketContext';

export default function Orders() {
  const { newOrderAlert } = useSocket();
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');

  // লাইভ ডাটাবেজ থেকে অর্ডার আনা
  const fetchOrders = async () => {
    try {
      setLoading(true);
      const res = await API.get('/orders');
      setOrders(res.data);
    } catch (err) {
      console.error('Failed to fetch orders:', err.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchOrders();
  }, []);

  // সকেটে নতুন অর্ডার এলে তালিকায় সাথে সাথে যোগ করা
  useEffect(() => {
    if (newOrderAlert) {
      setOrders((prev) => [newOrderAlert, ...prev]);
    }
  }, [newOrderAlert]);

  // স্ট্যাটাস পরিবর্তন করা (Live DB)
  const handleStatusChange = async (orderId, newStatus) => {
    const cleanId = String(orderId).replace('ORD-', '');
    try {
      await API.patch(`/orders/${cleanId}/status`, { status: newStatus });
      setOrders(orders.map((o) => (o.id === orderId ? { ...o, status: newStatus } : o)));
    } catch (err) {
      console.error('Status change error:', err.message);
    }
  };

  // সার্চ ফিল্টার
  const filteredOrders = orders.filter((order) => {
    const id = String(order.id || '');
    const phone = String(order.customer_phone || '');
    const name = String(order.customer_name || '').toLowerCase();
    const query = searchQuery.toLowerCase();
    return id.includes(query) || phone.includes(query) || name.includes(query);
  });

  return (
    <div className="p-8 space-y-6 bg-gray-50 min-h-screen">
      <div className="flex flex-col md:flex-row justify-between md:items-center gap-4">
        <div>
          <div className="flex items-center gap-3">
            <h1 className="text-2xl font-black text-gray-900 tracking-tight">Live Orders Console</h1>
            <span className="flex items-center gap-1 text-[11px] font-bold bg-emerald-100 text-emerald-800 px-2.5 py-0.5 rounded-full">
              <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
              Live Sync
            </span>
          </div>
          <p className="text-sm text-gray-500">সমস্ত অর্ডারের লাইভ অ্যাকশন, কল ও স্ট্যাটাস ওভাররাইড</p>
        </div>

        {/* সার্চ ও রিফ্রেশ বাটন */}
        <div className="flex items-center gap-3">
          <div className="relative">
            <Search className="w-4 h-4 absolute left-3 top-3 text-gray-400" />
            <input
              type="text"
              placeholder="Search by ID or Phone..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-9 pr-4 py-2 border border-gray-200 rounded-xl bg-white text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500 w-64"
            />
          </div>
          <button
            onClick={fetchOrders}
            className="p-2.5 bg-white border border-gray-200 rounded-xl hover:text-emerald-600 transition-colors shadow-sm"
            title="Refresh Orders"
          >
            <RefreshCw className="w-4 h-4" />
          </button>
        </div>
      </div>

      {loading ? (
        <div className="p-12 text-center text-gray-500 font-bold">অর্ডার লোড হচ্ছে...</div>
      ) : filteredOrders.length === 0 ? (
        <div className="bg-white p-12 text-center rounded-2xl border border-gray-100 text-gray-400 font-semibold">
          কোনো অর্ডার পাওয়া যায়নি
        </div>
      ) : (
        /* অর্ডার কার্ড তালিকা */
        <div className="grid grid-cols-1 gap-5">
          {filteredOrders.map((order) => (
            <div key={order.id} className="bg-white border border-emerald-100/80 rounded-2xl p-6 shadow-sm flex flex-col lg:flex-row justify-between gap-6 hover:shadow-md transition-shadow">

              {/* কাস্টমার ও ফুড বিবরণ */}
              <div className="space-y-3 flex-1">
                <div className="flex items-center gap-3">
                  <span className="px-3 py-1 bg-emerald-100 text-emerald-800 font-extrabold text-xs rounded-lg">
                    {String(order.id).startsWith('ORD-') ? order.id : `ORD-${order.id}`}
                  </span>
                  <span className="px-2.5 py-0.5 border border-emerald-200 text-emerald-700 text-xs font-bold rounded-md uppercase">
                    {order.payment_method} ({order.payment_status || 'Unpaid'})
                  </span>
                  <span className="text-xs text-gray-400">
                    {order.created_at ? new Date(order.created_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : 'Live'}
                  </span>
                </div>

                <div>
                  <h3 className="font-bold text-gray-900 text-base">{order.customer_name}</h3>
                  <p className="text-xs text-gray-500">{order.address}</p>
                </div>

                {/* কল ও মেসেজ বাটন */}
                <div className="flex items-center gap-2 pt-1">
                  <a
                    href={`tel:${order.customer_phone}`}
                    className="flex items-center gap-1.5 px-3 py-1.5 bg-emerald-50 text-emerald-700 border border-emerald-200 rounded-lg text-xs font-bold hover:bg-emerald-100"
                  >
                    <Phone className="w-3.5 h-3.5 text-emerald-600" /> {order.customer_phone}
                  </a>
                  <a
                    href={`https://wa.me/88${order.customer_phone}`}
                    target="_blank"
                    rel="noreferrer"
                    className="flex items-center gap-1.5 px-3 py-1.5 bg-emerald-600 text-white rounded-lg text-xs font-bold hover:bg-emerald-700"
                  >
                    <MessageSquare className="w-3.5 h-3.5" /> WhatsApp
                  </a>
                </div>

                {/* অর্ডার আইটেম নিরাপদে রেন্ডার করা */}
                <div className="bg-gray-50 p-3 rounded-xl border border-gray-100 text-xs">
                  <p className="font-bold text-emerald-950 mb-1">
                    Restaurant: {order.restaurant_name || 'Assigned Partner'}
                  </p>
                  <div className="text-gray-600 space-y-0.5">
                    {order.items && order.items.length > 0 ? (
                      order.items.map((item, idx) => (
                        <span key={idx} className="inline-block mr-3">• {item.name} × {item.qty}</span>
                      ))
                    ) : (
                      <span className="text-gray-400 italic">Custom Order Details (Check Customer/Partner)</span>
                    )}
                  </div>
                </div>
              </div>

              {/* রাইডার ইনফো ও স্ট্যাটাস চেঞ্জার */}
              <div className="lg:w-80 border-t lg:border-t-0 lg:border-l border-gray-100 lg:pl-6 flex flex-col justify-between space-y-4">
                <div className="bg-emerald-50/40 p-3 rounded-xl border border-emerald-100">
                  <p className="text-xs font-bold text-emerald-950 flex items-center gap-1.5 mb-1">
                    <Bike className="w-4 h-4 text-emerald-600" /> Assigned Rider
                  </p>
                  <p className="text-sm font-semibold text-gray-800">{order.rider_name || 'No rider assigned yet'}</p>
                  {order.rider_phone && (
                    <a href={`tel:${order.rider_phone}`} className="text-xs text-emerald-600 hover:underline font-bold mt-1 inline-block">
                      Call Rider ({order.rider_phone})
                    </a>
                  )}
                </div>

                <div>
                  <div className="flex justify-between items-center mb-2">
                    <span className="text-xs font-bold text-gray-500">Bill Amount:</span>
                    <span className="text-lg font-black text-emerald-600">৳ {order.total_amount}</span>
                  </div>

                  <label className="text-xs font-bold text-gray-500 uppercase tracking-wider block mb-1">Change Order Status</label>
                  <select
                    value={order.status || 'pending'}
                    onChange={(e) => handleStatusChange(order.id, e.target.value)}
                    className="w-full bg-white border border-emerald-300 text-gray-800 text-sm font-bold rounded-xl px-3 py-2 focus:ring-2 focus:ring-emerald-500 focus:outline-none"
                  >
                    <option value="pending">⏳ Pending</option>
                    <option value="confirmed">✅ Confirmed</option>
                    <option value="preparing">🍳 Preparing / Cooking</option>
                    <option value="out_for_delivery">🛵 Out For Delivery</option>
                    <option value="delivered">🎉 Delivered</option>
                    <option value="cancelled">❌ Cancelled</option>
                  </select>
                </div>
              </div>

            </div>
          ))}
        </div>
      )}
    </div>
  );
}
